contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address from, address caddress, address target) public payable {
        require(target != address(0));
        require(caddress != address(0));
        require(target != caddress);
        require(msg.value == 0);

        address[] memory tos = new address[](1);
        tos[0] = target;

        uint balBefore = target.balance;

        bool reverted;
        try c.transfer(from, caddress, tos, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = target.balance;

        assert(reverted || (caddress == target && balAfter == balBefore));
    }
}

