    function run(address from, address caddress, address target, uint amount) public payable {
        require(amount == 0);
        require(address(this).balance >= amount);

        address[] memory tos = new address[](1);
        tos[0] = target;

        uint balBefore = target.balance;

        bool reverted;
        try c.transfer(from, caddress, tos, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = target.balance;

        assert(reverted || balAfter == balBefore);
    }
}
